import{z as i,x as p,o as e,c as n,q as A,j as d,D as t,d as r,s as l,S as B,b as E}from"./chunks/framework.C8m1ZpeB.js";const C=JSON.parse('{"title":"组合逻辑时延","description":"","frontmatter":{"title":"组合逻辑时延","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/gate-delay.md","filePath":"cs/gate-delay.md","lastUpdated":1791063341000}'),o={name:"cs/gate-delay.md"};function _(D,a,m,c,h,F){const s=p("Mermaid");return e(),n("div",null,[a[2]||(a[2]=A('<h1 id="组合逻辑时延" tabindex="-1">组合逻辑时延 <a class="header-anchor" href="#组合逻辑时延" aria-label="Permalink to &quot;组合逻辑时延&quot;">​</a></h1><div class="epigraph"><p>功能对了还不够：输出必须在最坏输入变化后的某个时刻才稳定，那个时刻就是传播延迟。</p><footer>—— 据 Harris and Harris, Digital Design and Computer Architecture 整理</footer></div><p>上一课<a href="/cs/transmission-tristate">传输门与三态</a>钉死了任意组合功能都能落成门网。本课不重证 NAND 完备，也不从电磁场另起。缺口是：卡诺图与布尔式都不含时间。CMOS 对电容充放电需要时间；后课时钟周期不能短于这段时间。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>网表在直流上实现 \\(f\\)。输入同时变，输出要经过若干级才到新值，途中可以有<a href="/cs/dont-care-hazard">险象课</a>的毛刺。缺口因此不是新门，而是两个数：\\(t_{pd}\\) 传播延迟（最坏稳定时间）、\\(t_{cd}\\) 污染延迟（最早可能变）。时序约束用前者定周期下界，用后者防保持时间失败——保持是<a href="/cs/setup-hold">建立保持</a>的缺口，本课先把组合块当成有延迟的盒子。</p><p>关键路径是拓扑上延迟之和最大的那条。本课用单位门延迟作加法模型，不把 RC 树 Elmore 公式写完。</p><h3 id="不是仿真里「看起来稳了」的一次波形" tabindex="-1">\\(t_{pd}\\) 不是仿真里「看起来稳了」的一次波形 <a class="header-anchor" href="#不是仿真里「看起来稳了」的一次波形" aria-label="Permalink to &quot;$t_{pd}$ 不是仿真里「看起来稳了」的一次波形&quot;">​</a></h3><p>必须对输入对、温度、工艺角取最坏。功能仿真通过不等于时序通过。把扇出当成免费，关键路径会少算几级反相器缓冲。</p><p><span class="marginnote">Harris 把组合逻辑画成带 \\(t_{pd}\\)/\\(t_{cd}\\) 的云。后课单周期 CPU 的周期就是最长指令的组合路径。本课不引入触发器。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>每级门赋延迟（可按扇入扇出加权）。\\(t_{pd}(\\mathrm{path})=\\sum t_{pd,i}\\)，电路 \\(t_{pd}\\) 取全体输入-输出路径最大。污染延迟取最小。多级化简可能减逻辑深度，但扇出变大，延迟不一定降——与卡诺图「项更少」不是同一目标。</p>',11)),(e(),d(B,null,{default:t(()=>[l(s,{id:"mermaid-31",class:"mermaid",graph:"flowchart%20TD%0A%20%20NET%5B%22%E5%8A%9F%E8%83%BD%E6%AD%A3%E7%A1%AE%E7%9A%84%E7%BD%91%E8%A1%A8%22%5D%20--%3E%20DEL%5B%22%E6%AF%8F%E7%BA%A7%E5%85%85%E6%94%BE%E7%94%B5%22%5D%0A%20%20DEL%20--%3E%20TPD%5B%22t_pd%20%E6%9C%80%E5%9D%8F%E7%A8%B3%E5%AE%9A%22%5D%0A%20%20DEL%20--%3E%20TCD%5B%22t_cd%20%E6%9C%80%E6%97%A9%E5%8F%98%22%5D%0A%20%20TPD%20--%3E%20LATER%5B%22%E5%90%8E%E8%AF%BE%EF%BC%9AMUX%20%E7%AD%89%E5%9D%97%22%5D%0A"})]),fallback:t(()=>[...a[0]||(a[0]=[r(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=E("h2",{id:"机制",tabindex:"-1"},[r("机制 "),E("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[4]||(a[4]=E("p",null,"后课加法器的行波进位 \\(t_{pd}\\) 随位宽线性涨，才有超前进位。MUX、ALU 都先当组合云，用本课的尺子比深度。时钟仍未进场：组合电路没有「周期」，只有从输入变到输出稳的时间。",-1)),a[5]||(a[5]=E("p",null,"险象的毛刺落在 \\(t_{cd}\\) 与 \\(t_{pd}\\) 之间。若下游是纯组合，毛刺继续走；若下游是边沿采样，要看是否落在窗口外。",-1)),a[6]||(a[6]=E("p",null,"同一条电路，为什么最坏路径说了算？输出「定稿」的时间由最长的那条路径决定，短路径早就稳了。",-1)),(e(),d(B,null,{default:t(()=>[l(s,{id:"mermaid-44",class:"mermaid",graph:"flowchart%20TD%0A%20%20IN%5B%22%E8%BE%93%E5%85%A5%E5%90%8C%E6%97%B6%E7%BF%BB%E8%BD%AC%22%5D%20--%3E%20FAST%5B%22%E7%9F%AD%E8%B7%AF%E5%BE%84%EF%BC%9A%E7%A9%BF%E4%B8%80%E4%B8%A4%E7%BA%A7%E9%97%A8%E5%B0%B1%E7%A8%B3%E5%AE%9A%22%5D%0A%20%20IN%20--%3E%20SLOW%5B%22%E5%85%B3%E9%94%AE%E8%B7%AF%E5%BE%84%EF%BC%9A%E9%80%90%E7%BA%A7%E7%A9%BF%E8%BF%87%E6%9C%80%E9%95%BF%E9%97%A8%E9%93%BE%22%5D%0A%20%20FAST%20--%3E%20EARLY%5B%22%E6%9C%80%E6%97%A9%E5%8F%98%E5%8C%96%E7%82%B9%EF%BC%9At_cd%20%E6%B1%A1%E6%9F%93%E5%BB%B6%E8%BF%9F%22%5D%0A%20%20SLOW%20--%3E%20MID%5B%22%E9%80%94%E4%B8%AD%E8%BE%93%E5%87%BA%E5%8F%AF%E8%83%BD%E6%9D%A5%E5%9B%9E%E6%8A%96%E5%8A%A8%EF%BC%88%E6%AF%9B%E5%88%BA%EF%BC%89%22%5D%0A%20%20MID%20--%3E%20STABLE%5B%22%E6%9C%80%E7%BB%88%E7%A8%B3%E5%AE%9A%EF%BC%9At_pd%20%E4%BC%A0%E6%92%AD%E5%BB%B6%E8%BF%9F%22%5D%0A%20%20STABLE%20--%3E%20CLK%5B%22%E5%90%8E%E8%AF%BE%E6%97%B6%E9%92%9F%E5%91%A8%E6%9C%9F%E5%BF%85%E9%A1%BB%20%E2%89%A5%20t_pd%22%5D%0A"})]),fallback:t(()=>[...a[1]||(a[1]=[r(" Loading... ",-1)])]),_:1})),a[7]||(a[7]=A('<p><span class="marginnote">数字实例：设每级门延迟 20 ps，一个 32 位行波进位加法器关键路径要穿约 32 级进位链，光进位就是 32 × 20 ps = 640 ps，还没算生成与和项——位宽一大就撑不住，这正是超前进位存在的理由。</span></p><p><span class="marginnote">常见误区：初学者容易以为「布尔式化简后项更少，电路就更快」。项数少只说明门数少；延迟看的是最长路径的级数（深度）。有时故意多留几级冗余逻辑，反而能削短关键路径。</span></p><p><span class="marginnote">术语翻译：\\(t_{pd}\\) 是「最晚几点答案定稿」，\\(t_{cd}\\) 是「最早几点旧答案开始作废」。两者之间的窗口里输出新旧不定，毛刺就活在这段窗口里；下游若靠边沿采样，必须躲开这个窗口。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不讲时钟树、不讲互连铜线上的飞行时间作为主模型（承认线电容折进门负载即可）。不把异步组合反馈（环振）当合法数字设计——那是有意的模拟/测试结构。</p><p>后课默认：每个组合块带 \\(t_{pd}\\)、\\(t_{cd}\\)；关键路径决定后课能跑多快。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>组合正确性之外必须计量 \\(t_{pd}\\) 与 \\(t_{cd}\\)。</li><li>关键路径是最坏延迟和；项数少不等于深度小。</li><li>时钟与触发器仍未出现；本课只给组合盒子贴时间。</li><li>出处：Harris and Harris。</li></ul>',8))])}const f=i(o,[["render",_]]);export{C as __pageData,f as default};
